# region: shape
def shape(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: gather
def gather(xs, floor_=3):
    return [v for v in xs if v > floor_]

# region: sift
def sift(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: intake
def intake(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return intake(sift(gather(shape(raw))))

